    for k, vi, en in [
        ('mutex', 'KDoc: Animatable bảo đảm các animation loại trừ nhau; animation mới hủy animation đang chạy bằng CancellationException, và mọi việc sau đó trong coroutine gọi nó cũng bị hủy. [[src:an-animatable-src]]', 'The KDoc: Animatable ensures its animations are mutually exclusive; a new animation cancels the running one with a CancellationException, and all subsequent work in the caller\'s coroutine is cancelled too. [[src:an-animatable-src]]'),
        ('continuous', 'KDoc: animateTo giữa chừng đi từ giá trị tại điểm bị ngắt, nên luôn liên tục; với spring thì vận tốc cũng liên tục. [[src:an-animatable-src]]', 'The KDoc: animateTo mid-flight starts from the value at the point of interruption, so it is always continuous; with a spring, velocity is continuous too. [[src:an-animatable-src]]'),
        ('stop', 'KDoc: `stop()` không đưa giá trị tới đích, mà dừng tại chỗ; muốn đặt giá trị thì dùng `snapTo`. [[src:an-animatable-src]]', 'The KDoc: `stop()` does not skip the value to its target; it stops in its tracks; to set a value, use `snapTo`. [[src:an-animatable-src]]'),
        ('flow', 'Luồng của tài liệu: chạm → stop; kéo → snapTo + VelocityTracker; thả → calculateTargetValue rồi animateTo(0, velocity) hoặc animateDecay. [[src:an-advanced]]', 'The docs\' flow: touch → stop; drag → snapTo + VelocityTracker; release → calculateTargetValue then animateTo(0, velocity) or animateDecay. [[src:an-advanced]]'),
        ('bound', 'Mã ở commit ghim: giá trị bị kẹp trong biên, animation bị hủy, endReason = BoundReached; endAnimation đặt vận tốc về 0. Muốn giữ đà, lấy vận tốc trong `AnimationResult.endState`. [[src:an-animatable-src]]', 'Code at the pinned commit: the value is clamped to the bounds, the animation is cancelled, endReason = BoundReached; endAnimation resets velocity to 0. To keep the momentum, take the velocity from `AnimationResult.endState`. [[src:an-animatable-src]]')]:
        m('co.' + k, vi, en)
    a('cap.mutex', 'Ngón tay hoặc lời gọi bên trái đi vào Animatable; Animatable đổi vị trí thẻ bên phải; nhánh dưới là coroutine của lời gọi cũ bị hủy.', 'The finger or call on the left goes into the Animatable; the Animatable changes the card position on the right; the lower branch is the old call\'s coroutine being cancelled.')

    C = 'c6'
    a(C + '.sim.animation.mutex', 'Một animation một lúc', 'One animation at a time')
